    auto collection=DlsDocument::create();require(collection.add_wave_pcm(wav.encode(),"Part Tone")&&collection.create_instrument(0,8,"Part Tone",0)&&collection.set_wave_loops(0,{{0,0,16000}})&&collection.inherit_wave_sample(0,0),"Create owned sustained DLS tone for part assignment");const auto collectionBytes=collection.save_bytes();write_file_atomic((base/L"Tone.dlp").wstring(),collectionBytes);
