    require(!host.assign_sequence_collection_instrument(si,0,0,ci,0)&&host.document(si).save_bytes()==assigned,"Unchanged DLS assignment is a document and history no-op");
    require(host.document(si).undo()&&host.document(si).save_bytes()==unassigned&&!host.document(si).can_undo()&&host.document(si).redo()&&host.document(si).save_bytes()==assigned,"DLS reference plus locale is one Segment undo redo transaction");
    BandDocument beforeBand,afterBand;beforeBand.load(seed.band_events()[0].band);afterBand.load(host.document(si).band_events()[0].band);const auto beforeChannels=beforeBand.instruments(),afterChannels=afterBand.instruments();require(beforeChannels[1].flags==afterChannels[1].flags&&beforeChannels[1].patch==afterChannels[1].patch&&beforeChannels[1].pan==afterChannels[1].pan&&beforeChannels[1].volume==afterChannels[1].volume,"DLS assignment leaves unrelated PChannel patch and mix unchanged");
    require(!host.assign_sequence_collection_instrument(si,0,0,ci,99)&&host.document(si).save_bytes()==assigned,"Invalid DLS instrument index is atomic");
    host.save_segment(si,(base/L"Song.sgp").wstring());host.save_project((base/L"sequence-parts.pro").wstring());Framework loaded;loaded.open_project((base/L"sequence-parts.pro").wstring());require(loaded.document(0).save_bytes()==assigned&&loaded.playback_collections(0)[0].bytes==collectionBytes,"Saved project restores Sequence DLS identity and exact dependency");
