    require(host.collection_document(emptyCollection).instruments().empty()&&host.assign_sequence_collection_patch(si,0,0,emptyCollection,0,16),"Explicit empty collection accepts numeric bank0 patch16 observed in original Choose DLS");
    const auto manual=host.document(si).save_bytes();const auto manualPatch=sequence_patch(host.document(si),0,0);
    require(manualPatch&&manualPatch->patch==16&&collection_reference(manualPatch->collectionReference).objectId==collection_identity(host.collection_document(emptyCollection).save_bytes()),"Empty collection assignment persists requested locale and actual owned collection GUID without inventing an instrument");
    require(manualPatch->flags==0x1083u,"Original empty DLS selection retains existing default GM and enables zero transpose without activating mix");
