    require((emptyPreviewBand.instruments()[0].flags&0x1700u)==0x1000u&&collection_reference(emptyPreviewBand.instruments()[0].collectionReference).objectId==collection_identity(host.collection_document(emptyCollection).save_bytes()),"Empty DLS note audition retains the assigned collection and default GM preference");
