    const std::vector<ResolvedCollection> emptyDependencies={{emptyPreviewRefs[0],L"C:\\owned\\Empty.dlp",emptyOwnedSource}};
    const auto emptyRuntime=prepare_collection_playback({emptyPreviewSource},emptyDependencies);SegmentDocument emptyRuntimeSong;emptyRuntimeSong.load(emptyRuntime.documents[0]);BandDocument emptyRuntimeBand;emptyRuntimeBand.load(emptyRuntimeSong.band_events()[0].band);
    require(emptyRuntime.collections.empty()&&document_collection_references(emptyRuntime.documents[0]).empty()&&emptyRuntimeBand.instruments()[0].patch==16&&(emptyRuntimeBand.instruments()[0].flags&0x1700u)==0x1100u,"Runtime empty DLS with explicit default GM marks the private requested patch as GM without loading an empty collection");
