    auto invalidEmptyDependencies=emptyDependencies;invalidEmptyDependencies[0].reference.filename=L"Wrong.dlp";rejected([&]{prepare_collection_playback({emptyPreviewSource},invalidEmptyDependencies);},"Empty GM fallback still rejects mismatched dependency context before publication");
    require(host.document(si).undo()&&host.document(si).save_bytes()==unassigned&&!host.document(si).dirty()&&host.document(si).can_redo(),"Manual DLS locale and reference undo in one transaction");
    require(!host.assign_sequence_collection_patch(si,0,0,emptyCollection,0,128)&&!host.assign_sequence_collection_patch(si,0,0,emptyCollection,0x80,16)&&!host.assign_sequence_collection_patch(si,0,0xfffffffcu,emptyCollection,0,16)&&!host.assign_sequence_collection_patch(si,0,0,host.collections().size(),0,16)&&host.document(si).save_bytes()==unassigned&&!host.document(si).dirty()&&!host.document(si).can_undo()&&host.document(si).can_redo(),"Invalid manual locale collection and reserved channel preserve complete bytes dirty and redo checkpoint");
    require(host.document(si).redo()&&host.document(si).save_bytes()==manual&&!host.assign_sequence_collection_patch(si,0,0,emptyCollection,0,16)&&host.document(si).save_bytes()==manual,"Manual locale redo is exact and repeated accepted locale is a history no-op");
