    auto noDefault=seed;require(noDefault.update_band(0,0,0,noDefaultBand.encode()),"Prepare an empty DLS control with default GM disabled and unspecified transpose storage");host.document(si).load(noDefault.save_bytes());const auto noDefaultBefore=host.document(si).save_bytes();
